#include <iostream>
#include <vector>
#include <limits>
#include <algorithm>

using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    vector<int64> divisors;
    for (int64 i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i)
                divisors.push_back(n / i);
        }
    }

    int64 mina = numeric_limits<int64>::max();
    int64 maxa = numeric_limits<int64>::min();

    for (int64 a : divisors) {
        for (int64 b : divisors) {
            if ((n / a) % b != 0)
                continue;

            int64 c = n / a / b;
            int64 cur = (a + 1) * (b + 2) * (c + 2);

            mina = min(mina, cur);
            maxa = max(maxa, cur);
        }
    }

    cout << mina - n << ' ' << maxa - n << '\n';
    return 0;
}

