#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

using int64 = long long;
using int128 = __int128_t;

void printInt128(int128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(static_cast<char>('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    vector<int64> divisors;
    for (int64 i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i)
                divisors.push_back(n / i);
        }
    }

    int128 minimum = -1;
    int128 maximum = -1;

    for (int64 a : divisors) {
        for (int64 b : divisors) {
            if ((n / a) % b != 0)
                continue;

            int64 c = n / a / b;
            int128 current = static_cast<int128>(a + 1) *
                             static_cast<int128>(b + 2) *
                             static_cast<int128>(c + 2);

            if (minimum == -1 || current < minimum)
                minimum = current;
            if (maximum == -1 || current > maximum)
                maximum = current;
        }
    }

    printInt128(minimum - n);
    cout << ' ';
    printInt128(maximum - n);
    cout << '\n';

    return 0;
}

